"use client";

import * as React from "react";

export type LoginTwoFactorMethod = "app" | "sms" | "key";

export interface LoginTwoFactorChoiceLink {
  label: string;
  href: string;
}

export interface LoginTwoFactorChoiceValues {
  method: LoginTwoFactorMethod;
  code: string;
}

export interface LoginTwoFactorChoiceProps extends Omit<React.HTMLAttributes<HTMLElement>, "title" | "onSubmit"> {
  title?: string;
  subtitle?: string;
  phone?: string;
  keyName?: string;
  defaultMethod?: LoginTwoFactorMethod;
  defaultStep?: 1 | 2;
  methods?: LoginTwoFactorMethod[];
  onMethodChange?: (method: LoginTwoFactorMethod) => void;
  onSubmit?: (values: LoginTwoFactorChoiceValues) => boolean | void | Promise<boolean | void>;
  recovery?: LoginTwoFactorChoiceLink;
  accent?: string;
}

const css = `
.hb-qh7 {
  --hb-qh7-accent: #f59e0b;
  position: relative;
  box-sizing: border-box;
  width: 100%;
  overflow: hidden;
  container-type: inline-size;
  background: #0a0a0a;
  color: #ededed;
  font-family: inherit;
  padding: clamp(64px, 9cqw, 112px) 20px;
}
.hb-qh7 *, .hb-qh7 *::before, .hb-qh7 *::after { box-sizing: border-box; }
.hb-qh7::before { content: ""; position: absolute; left: -10%; top: -40%; width: 70%; height: 110%; pointer-events: none; background: conic-gradient(from 200deg at 50% 50%, transparent, color-mix(in srgb, var(--hb-qh7-accent) 22%, transparent), transparent 40%); filter: blur(70px); opacity: .7; animation: hb-qh7-sway 14s ease-in-out infinite alternate; }
.hb-qh7-inner { position: relative; max-width: 1040px; margin: 0 auto; display: grid; gap: 36px; align-items: start; }
.hb-qh7-tag { display: inline-flex; align-items: center; gap: 8px; font-size: 12px; letter-spacing: .1em; text-transform: uppercase; color: var(--hb-qh7-accent); }
.hb-qh7-title { margin: 14px 0 10px; font-size: clamp(30px, 4.4cqw, 44px); line-height: 1.05; letter-spacing: -.03em; font-weight: 600; }
.hb-qh7-sub { margin: 0; max-width: 380px; color: #8f8f8f; font-size: 15px; line-height: 1.6; }
.hb-qh7-steps { list-style: none; margin: 32px 0 0; padding: 0; display: grid; gap: 0; }
.hb-qh7-step { position: relative; display: flex; align-items: center; gap: 14px; padding: 10px 0; font-size: 14px; color: #6f6f6f; transition: color .3s; }
.hb-qh7-step:not(:last-child)::after { content: ""; position: absolute; left: 13px; top: 38px; width: 2px; height: 16px; border-radius: 2px; background: #262626; }
.hb-qh7-step[data-state="done"]:not(:last-child)::after { background: var(--hb-qh7-accent); }
.hb-qh7-num { flex: none; width: 28px; height: 28px; border-radius: 50%; display: grid; place-items: center; font-size: 12px; font-weight: 600; border: 1.5px solid #333; background: #0a0a0a; transition: all .3s; }
.hb-qh7-step[data-state="current"] { color: #ededed; }
.hb-qh7-step[data-state="current"] .hb-qh7-num { border-color: var(--hb-qh7-accent); color: var(--hb-qh7-accent); box-shadow: 0 0 0 4px color-mix(in srgb, var(--hb-qh7-accent) 15%, transparent); }
.hb-qh7-step[data-state="done"] { color: #a1a1a1; }
.hb-qh7-step[data-state="done"] .hb-qh7-num { background: var(--hb-qh7-accent); border-color: var(--hb-qh7-accent); color: #1a1003; }
.hb-qh7-card { border-radius: 22px; border: 1px solid rgba(255,255,255,.08); background: rgba(17,17,17,.92); box-shadow: inset 0 1px 0 rgba(255,255,255,.05), 0 30px 80px -40px rgba(0,0,0,.9); padding: clamp(20px, 3cqw, 28px); }
.hb-qh7-fs { border: 0; margin: 0; padding: 0; display: grid; gap: 10px; }
.hb-qh7-legend { padding: 0; margin-bottom: 14px; font-size: 15px; font-weight: 600; }
.hb-qh7-opt { position: relative; display: flex; align-items: center; gap: 14px; padding: 16px; border-radius: 16px; border: 1px solid #262626; background: #131313; cursor: pointer; transition: border-color .25s, background .25s, transform .25s; }
.hb-qh7-opt:hover { border-color: #3a3a3a; background: #161616; }
.hb-qh7-opt input { position: absolute; opacity: 0; width: 1px; height: 1px; }
.hb-qh7-opt:has(input:checked) { border-color: var(--hb-qh7-accent); background: color-mix(in srgb, var(--hb-qh7-accent) 7%, #131313); }
.hb-qh7-opt:has(input:focus-visible) { outline: 2px solid var(--hb-qh7-accent); outline-offset: 2px; }
.hb-qh7-ico { flex: none; width: 42px; height: 42px; border-radius: 12px; display: grid; place-items: center; background: #1b1b1b; border: 1px solid #2a2a2a; color: #d4d4d4; transition: color .25s, background .25s; }
.hb-qh7-opt:has(input:checked) .hb-qh7-ico { color: var(--hb-qh7-accent); background: color-mix(in srgb, var(--hb-qh7-accent) 12%, #151515); }
.hb-qh7-otext { display: grid; gap: 3px; min-width: 0; }
.hb-qh7-oname { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; font-size: 14.5px; font-weight: 500; }
.hb-qh7-odesc { font-size: 13px; color: #8f8f8f; }
.hb-qh7-badge { height: 20px; padding: 0 8px; border-radius: 999px; display: inline-flex; align-items: center; font-size: 11px; font-weight: 600; color: var(--hb-qh7-accent); background: color-mix(in srgb, var(--hb-qh7-accent) 14%, transparent); }
.hb-qh7-radio { margin-left: auto; flex: none; width: 20px; height: 20px; border-radius: 50%; border: 1.5px solid #3a3a3a; display: grid; place-items: center; transition: border-color .25s; }
.hb-qh7-radio::after { content: ""; width: 10px; height: 10px; border-radius: 50%; background: var(--hb-qh7-accent); transform: scale(0); transition: transform .3s cubic-bezier(.3,1.6,.5,1); }
.hb-qh7-opt:has(input:checked) .hb-qh7-radio { border-color: var(--hb-qh7-accent); }
.hb-qh7-opt:has(input:checked) .hb-qh7-radio::after { transform: scale(1); }
.hb-qh7-bar { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-top: 20px; }
.hb-qh7-btn { height: 46px; padding: 0 22px; border: 0; border-radius: 12px; display: inline-flex; align-items: center; justify-content: center; gap: 10px; background: var(--hb-qh7-accent); color: #1a1003; font: inherit; font-size: 14px; font-weight: 600; cursor: pointer; transition: filter .2s; }
.hb-qh7-btn:hover { filter: brightness(1.08); }
.hb-qh7-btn:disabled { cursor: progress; }
.hb-qh7-back { height: 46px; padding: 0 14px; border: 0; border-radius: 12px; background: transparent; color: #a1a1a1; font: inherit; font-size: 14px; cursor: pointer; display: inline-flex; align-items: center; gap: 6px; }
.hb-qh7-back:hover { color: #ededed; background: #161616; }
.hb-qh7-link { color: #a1a1a1; font-size: 13px; text-decoration: underline; text-underline-offset: 3px; text-decoration-color: rgba(255,255,255,.2); border-radius: 3px; }
.hb-qh7-link:hover { color: #ededed; }
.hb-qh7-btn:focus-visible, .hb-qh7-back:focus-visible, .hb-qh7-link:focus-visible { outline: 2px solid var(--hb-qh7-accent); outline-offset: 2px; }
.hb-qh7-pane { animation: hb-qh7-in .45s cubic-bezier(.2,.7,.2,1) both; }
.hb-qh7-ph { display: flex; align-items: center; gap: 14px; margin-bottom: 18px; }
.hb-qh7-ph h3 { margin: 0 0 3px; font-size: 16px; font-weight: 600; }
.hb-qh7-ph p { margin: 0; color: #8f8f8f; font-size: 13.5px; }
.hb-qh7-label { display: block; margin-bottom: 8px; font-size: 13px; color: #a1a1a1; }
.hb-qh7-code { width: 100%; height: 60px; padding: 0 18px; border-radius: 14px; border: 1px solid #2a2a2a; background: #0c0c0c; color: #ededed; font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace); font-size: 28px; letter-spacing: .5em; text-align: center; outline: none; transition: border-color .2s, box-shadow .2s; }
.hb-qh7-code::placeholder { color: #333; }
.hb-qh7-code:focus { border-color: var(--hb-qh7-accent); box-shadow: 0 0 0 3px color-mix(in srgb, var(--hb-qh7-accent) 20%, transparent); }
.hb-qh7-code[aria-invalid="true"] { border-color: #f87171; }
.hb-qh7-err { margin: 8px 0 0; font-size: 12.5px; color: #fca5a5; }
.hb-qh7-note { margin: 10px 0 0; font-size: 12.5px; color: #6f6f6f; }
.hb-qh7-key { position: relative; height: 150px; border-radius: 16px; border: 1px dashed #2f2f2f; background: radial-gradient(circle at 50% 60%, color-mix(in srgb, var(--hb-qh7-accent) 12%, transparent), transparent 60%); display: grid; place-items: center; overflow: hidden; }
.hb-qh7-keysvg { width: 150px; animation: hb-qh7-plug 2.8s cubic-bezier(.4,0,.2,1) infinite; }
.hb-qh7-tap { position: absolute; left: 50%; top: 52%; width: 34px; height: 34px; margin: -17px 0 0 -17px; border-radius: 50%; border: 2px solid var(--hb-qh7-accent); opacity: 0; animation: hb-qh7-tap 2.8s ease-out infinite; }
.hb-qh7-spin { width: 15px; height: 15px; border-radius: 50%; border: 2px solid rgba(26,16,3,.3); border-top-color: #1a1003; animation: hb-qh7-turn .7s linear infinite; }
.hb-qh7-done { text-align: center; padding: 18px 0 6px; display: grid; justify-items: center; gap: 10px; animation: hb-qh7-in .45s ease both; }
.hb-qh7-done h3 { margin: 6px 0 0; font-size: 20px; }
.hb-qh7-done p { margin: 0; color: #8f8f8f; font-size: 14px; }
.hb-qh7-shield { width: 64px; height: 64px; border-radius: 20px; display: grid; place-items: center; background: color-mix(in srgb, var(--hb-qh7-accent) 15%, #111); border: 1px solid color-mix(in srgb, var(--hb-qh7-accent) 40%, transparent); color: var(--hb-qh7-accent); }
.hb-qh7-shield path:last-child { stroke-dasharray: 20; stroke-dashoffset: 20; animation: hb-qh7-draw .5s .2s ease forwards; }
@container (min-width: 820px) {
  .hb-qh7-inner { grid-template-columns: 1fr 1.15fr; gap: 64px; }
}
@keyframes hb-qh7-sway { to { transform: translateX(20%) rotate(20deg); } }
@keyframes hb-qh7-in { from { opacity: 0; transform: translateX(14px); } to { opacity: 1; transform: none; } }
@keyframes hb-qh7-plug { 0%, 15% { transform: translateX(-26px); } 40%, 100% { transform: translateX(0); } }
@keyframes hb-qh7-tap { 0%, 45% { opacity: 0; transform: scale(.4); } 55% { opacity: 1; } 85%, 100% { opacity: 0; transform: scale(2.2); } }
@keyframes hb-qh7-turn { to { transform: rotate(360deg); } }
@keyframes hb-qh7-draw { to { stroke-dashoffset: 0; } }
@media (prefers-reduced-motion: reduce) {
  .hb-qh7 *, .hb-qh7 *::before, .hb-qh7 *::after { animation: none !important; transition: none !important; }
  .hb-qh7-shield path:last-child { stroke-dashoffset: 0; }
}
`;

function Icon({ method }: { method: LoginTwoFactorMethod }) {
  const s = { fill: "none", stroke: "currentColor", strokeWidth: 1.6, strokeLinecap: "round" as const, strokeLinejoin: "round" as const };
  if (method === "app") {
    return <svg width="20" height="20" viewBox="0 0 20 20" aria-hidden="true"><rect x="5" y="2" width="10" height="16" rx="2.5" {...s} /><path d="M8.5 15h3" {...s} /><circle cx="10" cy="8.5" r="2.6" {...s} /><path d="M10 7.2v1.3l.9.6" {...s} /></svg>;
  }
  if (method === "sms") {
    return <svg width="20" height="20" viewBox="0 0 20 20" aria-hidden="true"><path d="M3 5.5A2.5 2.5 0 0 1 5.5 3h9A2.5 2.5 0 0 1 17 5.5v6a2.5 2.5 0 0 1-2.5 2.5H9l-4 3v-3h0A2 2 0 0 1 3 12V5.5Z" {...s} /><path d="M7 8.5h.01M10 8.5h.01M13 8.5h.01" {...s} strokeWidth={2.2} /></svg>;
  }
  return <svg width="20" height="20" viewBox="0 0 20 20" aria-hidden="true"><rect x="2" y="7" width="11" height="6" rx="2" {...s} /><path d="M13 8.5h4v3h-4" {...s} /><circle cx="6.5" cy="10" r="1.2" fill="currentColor" stroke="none" /></svg>;
}

const info: Record<LoginTwoFactorMethod, { name: string; desc: (phone: string, keyName: string) => string }> = {
  app: { name: "Authenticator app", desc: () => "6-digit code from your authenticator" },
  sms: { name: "Text message", desc: (phone) => `Send a code to ${phone}` },
  key: { name: "Security key", desc: (_p, keyName) => `Tap your ${keyName}` },
};

function wait(result: unknown) {
  return result instanceof Promise ? result : new Promise<unknown>((resolve) => setTimeout(() => resolve(result), 1100));
}

export function LoginTwoFactorChoice({
  title = "Confirm it's you",
  subtitle = "Your Atlas workspace requires two-step verification. Choose how you want to receive your code this time.",
  phone = "+1 ••• ••• 0142",
  keyName = "YubiKey 5C",
  defaultMethod = "app",
  defaultStep = 1,
  methods = ["app", "sms", "key"],
  onMethodChange,
  onSubmit,
  recovery = { label: "Use a recovery code", href: "#recovery" },
  accent = "#f59e0b",
  className = "",
  style,
  ...rest
}: LoginTwoFactorChoiceProps) {
  const uid = React.useId();
  const [method, setMethod] = React.useState<LoginTwoFactorMethod>(defaultMethod);
  const [step, setStep] = React.useState<1 | 2 | 3>(defaultStep);
  const [code, setCode] = React.useState("");
  const [error, setError] = React.useState("");
  const [busy, setBusy] = React.useState(false);
  const codeRef = React.useRef<HTMLInputElement>(null);

  function choose(next: LoginTwoFactorMethod) {
    setMethod(next);
    onMethodChange?.(next);
  }

  function goNext(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setStep(2);
    setCode("");
    setError("");
    window.setTimeout(() => codeRef.current?.focus(), 50);
  }

  async function verify(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (busy) return;
    if (method !== "key" && !/^\d{6}$/.test(code)) {
      setError("Enter all 6 digits.");
      codeRef.current?.focus();
      return;
    }
    setError("");
    setBusy(true);
    try {
      const result = await wait(onSubmit ? onSubmit({ method, code: method === "key" ? "" : code }) : true);
      if (result === false) setError(method === "key" ? "That key isn't registered to this account." : "That code is incorrect or expired.");
      else setStep(3);
    } catch {
      setError("Verification failed. Try again.");
    }
    setBusy(false);
  }

  const stepState = (n: number) => (step > n ? "done" : step === n ? "current" : "todo");

  return (
    <section className={`hb-qh7 ${className}`} style={{ "--hb-qh7-accent": accent, ...style } as React.CSSProperties} {...rest}>
      <style href="hb-login-two-factor-choice" precedence="default">{css}</style>
      <div className="hb-qh7-inner">
        <div>
          <span className="hb-qh7-tag">
            <svg width="14" height="14" viewBox="0 0 16 16" aria-hidden="true"><path d="M8 1.5 2.5 4v4c0 3.2 2.3 5.6 5.5 6.5 3.2-.9 5.5-3.3 5.5-6.5V4L8 1.5Z" fill="none" stroke="currentColor" strokeWidth="1.5" /></svg>
            Two-step verification
          </span>
          <h2 className="hb-qh7-title">{title}</h2>
          <p className="hb-qh7-sub">{subtitle}</p>
          <ol className="hb-qh7-steps">
            {["Choose a method", "Verify", "Signed in"].map((label, i) => (
              <li key={label} className="hb-qh7-step" data-state={stepState(i + 1)} aria-current={step === i + 1 ? "step" : undefined}>
                <span className="hb-qh7-num">{step > i + 1 ? (
                  <svg width="12" height="12" viewBox="0 0 12 12" aria-hidden="true"><path d="m2.5 6.2 2.3 2.3 4.7-5" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" /></svg>
                ) : i + 1}</span>
                {label}
              </li>
            ))}
          </ol>
        </div>
        <div className="hb-qh7-card">
          {step === 1 && (
            <form className="hb-qh7-pane" key="s1" onSubmit={goNext}>
              <fieldset className="hb-qh7-fs">
                <legend className="hb-qh7-legend">How do you want to verify?</legend>
                {methods.map((m) => (
                  <label key={m} className="hb-qh7-opt">
                    <input type="radio" name={`${uid}-m`} value={m} checked={method === m} onChange={() => choose(m)} />
                    <span className="hb-qh7-ico"><Icon method={m} /></span>
                    <span className="hb-qh7-otext">
                      <span className="hb-qh7-oname">{info[m].name}{m === "app" && <span className="hb-qh7-badge">Recommended</span>}</span>
                      <span className="hb-qh7-odesc">{info[m].desc(phone, keyName)}</span>
                    </span>
                    <span className="hb-qh7-radio" aria-hidden="true" />
                  </label>
                ))}
              </fieldset>
              <div className="hb-qh7-bar">
                <a className="hb-qh7-link" href={recovery.href}>{recovery.label}</a>
                <button type="submit" className="hb-qh7-btn">Continue
                  <svg width="14" height="14" viewBox="0 0 16 16" aria-hidden="true"><path d="M3 8h10M9 4l4 4-4 4" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" /></svg>
                </button>
              </div>
            </form>
          )}
          {step === 2 && (
            <form className="hb-qh7-pane" key="s2" noValidate onSubmit={verify}>
              <div className="hb-qh7-ph">
                <span className="hb-qh7-ico" style={{ color: accent }}><Icon method={method} /></span>
                <div>
                  <h3>{method === "app" ? "Enter the code from your app" : method === "sms" ? "Enter the code we texted you" : `Use your ${keyName}`}</h3>
                  <p>{method === "app" ? "Open your authenticator and find Atlas." : method === "sms" ? `Sent to ${phone}. It expires in 10 minutes.` : "Insert the key and tap the gold contact when it blinks."}</p>
                </div>
              </div>
              {method === "key" ? (
                <div className="hb-qh7-key" aria-hidden="true">
                  <svg className="hb-qh7-keysvg" viewBox="0 0 150 60">
                    <rect x="98" y="18" width="46" height="24" rx="4" fill="#1f1f1f" stroke="#333" />
                    <rect x="102" y="24" width="10" height="12" rx="1.5" fill="#2a2a2a" />
                    <rect x="8" y="14" width="84" height="32" rx="10" fill="#222" stroke="#3a3a3a" />
                    <rect x="88" y="22" width="20" height="16" rx="2" fill="#9ca3af" />
                    <circle cx="40" cy="30" r="9" fill="none" stroke={accent} strokeWidth="2" />
                    <circle cx="40" cy="30" r="4" fill={accent} />
                  </svg>
                  <span className="hb-qh7-tap" style={{ left: "calc(50% - 35px)" }} />
                </div>
              ) : (
                <div>
                  <label className="hb-qh7-label" htmlFor={`${uid}-code`}>Verification code</label>
                  <input ref={codeRef} id={`${uid}-code`} className="hb-qh7-code" inputMode="numeric" autoComplete="one-time-code" maxLength={6} placeholder="000000" value={code} aria-invalid={error ? true : undefined} aria-describedby={error ? `${uid}-err` : undefined} onChange={(e) => { setCode(e.target.value.replace(/\D/g, "").slice(0, 6)); if (error) setError(""); }} />
                  {method === "sms" && <p className="hb-qh7-note">Didn&apos;t get it? Wait 30 seconds, then go back and send again.</p>}
                </div>
              )}
              {error && <p className="hb-qh7-err" id={`${uid}-err`} role="alert">{error}</p>}
              <div className="hb-qh7-bar">
                <button type="button" className="hb-qh7-back" onClick={() => { setStep(1); setError(""); }}>
                  <svg width="14" height="14" viewBox="0 0 16 16" aria-hidden="true"><path d="M13 8H3M7 4 3 8l4 4" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" /></svg>
                  Other methods
                </button>
                <button type="submit" className="hb-qh7-btn" disabled={busy} aria-busy={busy}>
                  {busy && <span className="hb-qh7-spin" aria-hidden="true" />}
                  {busy ? (method === "key" ? "Waiting for key" : "Verifying") : method === "key" ? "Use security key" : "Verify"}
                </button>
              </div>
            </form>
          )}
          {step === 3 && (
            <div className="hb-qh7-done" role="status">
              <span className="hb-qh7-shield">
                <svg width="28" height="28" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2.5 4.5 5.5v6c0 4.6 3.2 8 7.5 9.5 4.3-1.5 7.5-4.9 7.5-9.5v-6L12 2.5Z" fill="none" stroke="currentColor" strokeWidth="1.6" /><path d="m8.5 12 2.5 2.5 4.5-5" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" /></svg>
              </span>
              <h3>Verified</h3>
              <p>Signed in with your {info[method].name.toLowerCase()}. Redirecting to Atlas.</p>
            </div>
          )}
        </div>
      </div>
    </section>
  );
}
